const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

class DriftDetector {
    constructor(opts = {}) {
        this.snapshots = new Map();   // key → { hash, ts, data }
        this.events = [];
        this.maxEvents = opts.maxEvents || 1000;
    }

    // ─── Hash content deterministically ──────────────────────────
    _hash(data) {
        return crypto.createHash("sha256")
            .update(typeof data === "string" ? data : JSON.stringify(data))
            .digest("hex")
            .substring(0, 16);
    }

    // ─── Take a snapshot of a key (registry, config, etc.) ───────
    snapshot(key, data) {
        const hash = this._hash(data);
        const prev = this.snapshots.get(key);

disableProvider(name) {
        if (this.providers[name]) {
            this.providers[name].enabled = false;
        }
    }

    listProviders() {
        return Object.entries(this.providers).map(([name, config]) => ({
            name,
            enabled: config.enabled,
            model: config.model,
            dims: config.dims,
        }));
    }

    // ─── Status ──────────────────────────────────────────────────
    status() {
        return {
            providers: this.listProviders(),
            preferredOrder: this.preferredOrder,
            cacheSize: this.cache.size,
            stats: { ...this.stats },
        };
    }
}

